import os, pty, sys, time, select, fcntl, termios, struct, subprocess

class Repl:
    def __init__(self, args=(), rows=24, cols=80):
        self.pid, self.fd = pty.fork()
        if self.pid == 0:
            os.execvp('./executable', ['./executable'] + list(args))
        fcntl.ioctl(self.fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
        self.buf = b''
        self.pending = []
    def send(self, s, delay=0.06):
        if isinstance(s, str): s = s.encode()
        os.write(self.fd, s)
        time.sleep(delay)
        return self.drain()
    def drain(self):
        out = b''
        while True:
            r,_,_ = select.select([self.fd], [], [], 0.05)
            if not r: break
            try: d = os.read(self.fd, 65536)
            except OSError: break
            if not d: break
            out += d
        return out
    def close(self):
        try: os.close(self.fd)
        except: pass
        try: os.kill(self.pid, 9)
        except: pass
        try: os.waitpid(self.pid, 0)
        except: pass

def show(b):
    print(repr(b))
