    r=subprocess.run(['./executable'],input=t+'\n',capture_output=True,text=True,timeout=5)
    out=r.stdout.strip().replace('No previous history.\n','')
    return out.split('\n')[-1]
alpha=['.','e','5','+']
res={}
for t in [''.join(c) for c in itertools.product(alpha,repeat=3)]:
    res[t]=run(t)
# group by result
g=collections.defaultdict(list)
for k,v in res.items(): g[v].append(k)
for v in sorted(g, key=lambda x: (len(g[x])*-1)):
    print('%-30s : %s' % (v, ' '.join(g[v])))
