fn parse_expr(&mut self) -> Result<f64, CalcErr> {
    let mut left = self.parse_term()?;
    loop {
        let c = self.peek();
        if c == Some(Tok::Op('+')) || c == Some(Tok::Op('-')) {
            self.pos += 1;
            let right = self.parse_term()?;
            left = match c { '+' => left + right, '-' => left - right, _ => unreachable };
        } else { break }
    }
    Ok(left)
}
```

