fn parse_term(&mut self) -> Result<f64, CalcErr> {
    let mut left = self.parse_factor()?;
    loop {
        match self.peek() {
            Some(Tok::Op('*')) | Some(Tok::Op('/')) | Some(Tok::Op('%')) => {
                let op = ...; self.pos += 1;
                let right = self.parse_factor()?;
                left = op(left, right)?;
            }
            _ => break
        }
    }
    Ok(left)
}
```

