// Calculator: tokenizer, parser and evaluator for the eva expression language.

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Angle {
    Degree,
    Radian,
    Gradian,
}

impl Angle {
    pub fn name(self) -> &'static str {
        match self {
            Angle::Degree => "degree",
            Angle::Radian => "radian",
            Angle::Gradian => "gradian",
        }
    }
}

#[derive(Clone, Debug, PartialEq)]
pub enum CalcErr {
    /// Syntax Error: ...
    Syntax(String),
    /// Parser Error: ...
    Parse(String),
    /// Math Error: ...
    Math(String),
    /// Domain Error: ...
    Domain(String),
    /// Error: to large to process! ...
    TooLarge,
}

impl CalcErr {
    pub fn message(&self) -> String {
        match self {
            CalcErr::Syntax(s) => format!("Syntax Error: {}", s),
            CalcErr::Parse(s) => format!("Parser Error: {}", s),
            CalcErr::Math(s) => format!("Math Error: {}", s),
            CalcErr::Domain(s) => format!("Domain Error: {}", s),
            CalcErr::TooLarge => format!(
                "Error: to large to process! Max value: {}",
                f64::MAX
            ),
        }
    }
}

#[derive(Clone, Debug, PartialEq)]
enum Tok {
    Num(f64),
    Const(&'static str),
    Func(&'static str),
    LParen,
    RParen,
    Comma,
    Op(char),
    Unknown(String),
    Invalid(String),
    DotOp,
    Prev,
}

const FNAMES_1: &[&str] = &[
    "sin", "cos", "tan", "csc", "sec", "cot", "sinh", "cosh", "tanh", "asin", "acos", "atan",
    "acsc", "asec", "acot", "ln", "log2", "log10", "sqrt", "ceil", "floor", "abs", "exp",
];

const FNAMES_2: &[&str] = &["log", "nroot"];

const CONSTANTS: &[&str] = &["pi", "e"];

// ---------------------------------------------------------------------------
// Tokenizer
// ---------------------------------------------------------------------------

struct Lexer {
    src: Vec<char>,
    i: usize,
    toks: Vec<Tok>,
    pending: Option<(usize, String)>,
}

impl Lexer {
    fn peek(&self) -> Option<char> {
        self.src.get(self.i).copied()
    }

    fn skip_spaces(&mut self) {
        while let Some(' ') = self.peek() {
            self.i += 1;
        }
    }

    fn push(&mut self, t: Tok) {
        // flush any pending dots as an operator-like token placed at their position
        if let Some((idx, _)) = self.pending.take() {
            self.toks.insert(idx, Tok::DotOp);
        }
        self.toks.push(t);
    }

    fn read_number(&mut self) {
        let mut num = String::new();
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() || c == '.' {
                num.push(c);
                self.i += 1;
            } else if c == ' ' {
                self.i += 1;
            } else {
                break;
            }
        }
        let has_digit = num.chars().any(|c| c.is_ascii_digit());
        if has_digit {
            let full = match self.pending.take() {
                Some((_, p)) => format!("{}{}", p, num),
                None => num.clone(),
            };
            match full.parse::<f64>() {
                Ok(v) => self.push(Tok::Num(v)),
                Err(_) => self.push(Tok::Invalid(full)),
            }
        } else {
            if self.i >= self.src.len() {
                self.push(Tok::Invalid(num));
            } else {
                let pos = self.toks.len();
                match self.pending.take() {
                    Some((_, p)) => {
                        self.pending = Some((pos, format!("{}{}", p, num)));
                    }
                    None => {
                        self.pending = Some((pos, num));
                    }
                }
            }
        }
    }

    fn read_ident(&mut self) {
        let mut letters = String::new();
        while let Some(c) = self.peek() {
            if c.is_ascii_alphabetic() {
                letters.push(c);
                self.i += 1;
            } else if c == ' ' {
                self.i += 1;
            } else {
                break;
            }
        }
        let next = self.peek();
        // Try longest known name (functions then constants) that is a prefix of
        // the remaining text (letters + one extra char).
        if let Some(c) = next {
            if c.is_ascii_digit() || c == '.' {
                let probe: String = format!("{}{}", letters, c);
                if let Some(idx) = longest_known(&probe) {
                    self.i += 1;
                    self.emit_known(probe[..idx].to_string());
                    return;
                }
                if let Some(idx) = longest_known(&letters) {
                    let _ = idx;
                    self.emit_known(letters.clone());
                    return;
                }
                // unknown identifier: consume trailing digits/dot greedily to
                // build the error token.
                let mut s = letters.clone();
                if c == '.' {
                    s.push('.');
                    self.i += 1;
                } else {
                    // scan forward over non-digit characters for a digit
                    while let Some(ch) = self.peek() {
                        if ch.is_ascii_digit() {
                            s.push(ch);
                            self.i += 1;
                            break;
                        } else {
                            self.i += 1;
                        }
                    }
                    if !self.ended_digit() {
                        // no digit found: only letters+dots matter
                    }
                }
                self.push(Tok::Invalid(s));
                return;
            }
        }
        if let Some(idx) = longest_known(&letters) {
            let _ = idx;
            self.emit_known(letters.clone());
        } else {
            self.push(Tok::Unknown(letters));
        }
    }

    fn ended_digit(&self) -> bool {
        false
    }

    fn emit_known(&mut self, name: String) {
        if CONSTANTS.contains(&name.as_str()) {
            self.push(Tok::Const(name));
        } else {
            self.push(Tok::Func(match name.as_str() {
                n => {
                    let _ = n;
                    ""
                }
            }));
        }
    }
}

fn longest_known(s: &str) -> Option<usize> {
    // longest prefix of s that is a known function or constant name
    let mut best: Option<usize> = None;
    for name in FNAMES_1.iter().chain(FNAMES_2.iter()).chain(CONSTANTS.iter()) {
        if s.len() >= name.len() && &s[..name.len()] == *name {
            if best.map(|b| b < name.len()).unwrap_or(true) {
                best = Some(name.len());
            }
        }
    }
    best
}

fn is_known(s: &str) -> bool {
    FNAMES_1.contains(&s) || FNAMES_2.contains(&s) || CONSTANTS.contains(&s)
}

fn known_arity(s: &str) -> usize {
    if FNAMES_2.contains(&s) {
        2
    } else {
        1
    }
}

pub fn tokenize(input: &str) -> Vec<Tok> {
    let mut lx = Lexer {
        src: input.chars().collect(),
        i: 0,
        toks: Vec::new(),
        pending: None,
    };
    while lx.i < lx.src.len() {
        lx.skip_spaces();
        if lx.i >= lx.src.len() {
            break;
        }
        let c = lx.peek().unwrap();
        if c.is_ascii_digit() || c == '.' {
            lx.read_number();
            continue;
        }
        if c.is_ascii_alphabetic() {
            lx.read_ident();
            continue;
        }
        match c {
            '+' | '-' | '*' | '/' | '^' | '%' => {
                lx.i += 1;
                lx.push(Tok::Op(c));
            }
            '(' => {
                lx.i += 1;
                lx.push(Tok::LParen);
            }
            ')' => {
                lx.i += 1;
                lx.push(Tok::RParen);
            }
            ',' => {
                lx.i += 1;
                lx.push(Tok::Comma);
            }
            '_' => {
                lx.i += 1;
                lx.push(Tok::Prev);
            }
            _ => {
                lx.i += 1;
                lx.push(Tok::Invalid(c.to_string()));
            }
        }
    }
    if let Some((idx, _)) = lx.pending.take() {
        lx.toks.insert(idx, Tok::DotOp);
    }
    lx.toks
}
