fn parse_primary(&mut self) -> Result<f64, CalcErr> {
    let t = self.toks.get(self.pos).cloned();
    match t {
        None => Err(Parse("Too many operators, too few operands")),
        Some(Tok::Num(v)) => { self.pos += 1; Ok(v) }
        Some(Tok::Const(c)) => { self.pos += 1; Ok(c.value()) }
        Some(Tok::Prev) => { self.pos += 1; match self.prev_ans { Some(p) => Ok(p), None => Err(Syntax("No previous answer!")) } }
        Some(Tok::LParen) => {
            self.pos += 1; self.depth += 1;
            let v = self.parse_expr()?;
            if self.peek() == Some(Tok::RParen) { self.pos += 1; } else { return Err(Syntax("Mismatched parentheses!")) }
            self.depth -= 1;
            Ok(v)
        }
        Some(Tok::RParen) => {
            if self.depth == 0 { Err(Syntax("Mismatched parentheses!")) } else { Err(Parse("Too many operators, too few operands")) }
        }
        Some(Tok::Comma) => {
            if self.depth == 0 { Err(Syntax("Mismatched parentheses!")) } else { Err(Parse("Too many operators, too few operands")) }
