        Some(Tok::Func(name)) => { ... }
        Some(Tok::Op(_)) => Err(Parse("Too many operators, too few operands")),
        Some(Tok::Unknown(_)) => Err(Parse("Too many operators, too few operands")),
        Some(Tok::Invalid(s)) => Err(Syntax(format!("Unexpected character '{}'", s))),
        Some(Tok::DotOp) => ...
    }
}
