// eva expression evaluator: tokenizer, parser, evaluation.

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Angle {
    Degree,
    Radian,
    Gradian,
}

impl Angle {
    pub fn name(self) -> &'static str {
        match self {
            Angle::Degree => "degree",
            Angle::Radian => "radian",
            Angle::Gradian => "gradian",
        }
    }
}

#[derive(Clone, Debug)]
pub enum CalcErr {
    Syntax(String),
    Parse(String),
    Math(String),
    Domain(String),
    TooLarge,
}

impl CalcErr {
    pub fn message(&self) -> String {
        match self {
            CalcErr::Syntax(s) => format!("Syntax Error: {}", s),
            CalcErr::Parse(s) => format!("Parser Error: {}", s),
            CalcErr::Math(s) => format!("Math Error: {}", s),
            CalcErr::Domain(s) => format!("Domain Error: {}", s),
            CalcErr::TooLarge => format!("Error: to large to process! Max value: {}", f64::MAX),
        }
    }
}

pub type CResult = Result<f64, CalcErr>;

const F1: &[&str] = &[
    "sin", "cos", "tan", "csc", "sec", "cot", "sinh", "cosh", "tanh", "asin", "acos", "atan",
    "acsc", "asec", "acot", "ln", "log2", "log10", "sqrt", "ceil", "floor", "abs", "exp", "round",
    "deg", "rad",
];
const F2: &[&str] = &["log", "nroot"];
const CONSTS: &[&str] = &["pi", "e"];

fn longest_known(s: &str) -> Option<usize> {
    let mut best: Option<usize> = None;
    for name in F1.iter().chain(F2.iter()).chain(CONSTS.iter()) {
        if s.len() >= name.len() && &s[..name.len()] == *name {
            match best {
                Some(b) if b >= name.len() => {}
                _ => best = Some(name.len()),
            }
        }
    }
    best
}

fn is_known(s: &str) -> bool {
    F1.contains(&s) || F2.contains(&s) || CONSTS.contains(&s)
}

fn known_arity(s: &str) -> usize {
    if F2.contains(&s) {
        2
    } else {
        1
    }
}

#[derive(Clone, Debug, PartialEq)]
enum Tok {
    Num(f64),
    Const(&'static str),
    Func(&'static str),
    LParen,
    RParen,
    Comma,
    Op(char),
    Unknown(String),
    Invalid(String),
    DotOp,
    Prev,
}

// ---------------------------------------------------------------------------
// Tokenizer
// ---------------------------------------------------------------------------

pub fn tokenize(input: &str) -> Vec<Tok> {
    let src: Vec<char> = input.chars().collect();
    let mut i = 0usize;
    let mut toks: Vec<Tok> = Vec::new();
    // pending dot-run: position where the DotOp token belongs, and the dots
    let mut pending: Option<(usize, String)> = None;

    macro_rules! flush_pending {
        () => {
            if let Some((idx, _)) = pending.take() {
                toks.insert(idx, Tok::DotOp);
            }
        };
    }

    while i < src.len() {
        let c = src[i];
        if c == ' ' {
            i += 1;
            continue;
        }
        if c.is_ascii_digit() || c == '.' {
            let mut num = String::new();
            while i < src.len() {
                let n = src[i];
                if n.is_ascii_digit() || n == '.' {
                    num.push(n);
                    i += 1;
                } else if n == ' ' {
                    i += 1;
                } else {
                    break;
                }
            }
            let has_digit = num.chars().any(|ch| ch.is_ascii_digit());
            if has_digit {
                let full = match pending.take() {
                    Some((_, p)) => format!("{}{}", p, num),
                    None => num.clone(),
                };
                let t = match full.parse::<f64>() {
                    Ok(v) => Tok::Num(v),
                    Err(_) => Tok::Invalid(full),
                };
                flush_pending!();
                toks.push(t);
            } else {
                if i >= src.len() {
                    // dots at end of input -> invalid token
                    flush_pending!();
                    toks.push(Tok::Invalid(num));
                } else {
                    // remember as pending; the DotOp slot is the current position
                    let pos = toks.len();
                    let p = match pending.take() {
                        Some((_, prev_dots)) => format!("{}{}", prev_dots, num),
                        None => num.clone(),
                    };
                    pending = Some((pos, p));
                }
            }
            continue;
        }
        if c.is_ascii_alphabetic() {
            // letters, possibly separated by spaces
            let mut letters = String::new();
            while i < src.len() {
                let n = src[i];
                if n.is_ascii_alphabetic() {
                    letters.push(n);
                    i += 1;
                } else if n == ' ' {
                    i += 1;
                } else {
                    break;
                }
            }
            let next = if i < src.len() { Some(src[i]) } else { None };
            match next {
                Some(ch) if ch.is_ascii_digit() => {
                    // read the digit run and try to match a known name
                    let mut digits = String::new();
                    while i < src.len() && src[i].is_ascii_digit() {
                        digits.push(src[i]);
                        i += 1;
                    }
                    let mut matched = false;
                    for k in (1..=digits.len()).rev() {
                        let probe = format!("{}{}", letters, &digits[..k]);
                        if is_known(&probe) {
                            flush_pending!();
                            toks.push(known_tok(&probe));
                            matched = true;
                            // rest of digits become a number
                            let rest = &digits[k..];
                            if !rest.is_empty() {
                                push_number(&mut toks, &mut pending, rest);
                            }
                            break;
                        }
                    }
                    if !matched {
                        if is_known(&letters) {
                            flush_pending!();
                            toks.push(known_tok(&letters));
                            push_number(&mut toks, &mut pending, &digits);
                        } else {
                            flush_pending!();
                            toks.push(Tok::Invalid(format!("{}{}", letters, &digits[..1])));
                        }
                    }
                    continue;
                }
                Some('.') => {
                    if is_known(&letters) {
                        flush_pending!();
                        toks.push(known_tok(&letters));
                        // the '.' will be handled by the number reader
                    } else {
                        flush_pending!();
                        toks.push(Tok::Invalid(format!("{}.", letters)));
                        i += 1;
                    }
                    continue;
                }
                _ => {
                    if is_known(&letters) {
                        flush_pending!();
                        toks.push(known_tok(&letters));
                    } else {
                        // scan forward for a digit, skipping spaces/operators
                        let mut s = letters.clone();
                        let mut consumed = false;
                        while i < src.len() {
                            let ch = src[i];
                            if ch == ' ' || ch == '+' || ch == '-' || ch == '*' || ch == '/'
                                || ch == '^' || ch == '%'
                            {
                                i += 1;
                            } else if ch.is_ascii_digit() {
                                s.push(ch);
                                i += 1;
                                consumed = true;
                                break;
                            } else {
                                break;
                            }
                        }
                        flush_pending!();
                        if consumed {
                            toks.push(Tok::Invalid(s));
                        } else {
                            toks.push(Tok::Unknown(s));
                        }
                    }
                    continue;
                }
            }
        }
        match c {
            '+' | '-' | '*' | '/' | '^' | '%' => {
                i += 1;
                flush_pending!();
                toks.push(Tok::Op(c));
            }
            '(' => {
                i += 1;
                flush_pending!();
                toks.push(Tok::LParen);
            }
            ')' => {
                i += 1;
                flush_pending!();
                toks.push(Tok::RParen);
            }
            ',' => {
                i += 1;
                flush_pending!();
                toks.push(Tok::Comma);
            }
            '_' => {
                i += 1;
                flush_pending!();
                toks.push(Tok::Prev);
            }
            _ => {
                i += 1;
                flush_pending!();
                toks.push(Tok::Invalid(c.to_string()));
            }
        }
    }
    if let Some((idx, _)) = pending.take() {
        toks.insert(idx, Tok::DotOp);
    }
    toks
}

fn known_tok(name: &str) -> Tok {
    if CONSTS.contains(&name) {
        Tok::Const(name)
    } else {
        Tok::Func(name)
    }
}

fn push_number(toks: &mut Vec<Tok>, pending: &mut Option<(usize, String)>, digits: &str) {
    let full = match pending.take() {
        Some((_, p)) => format!("{}{}", p, digits),
        None => digits.to_string(),
    };
    match full.parse::<f64>() {
        Ok(v) => toks.push(Tok::Num(v)),
        Err(_) => toks.push(Tok::Invalid(full)),
    }
}

// ---------------------------------------------------------------------------
// Parser / evaluator
// ---------------------------------------------------------------------------

struct Parser {
    toks: Vec<Tok>,
    pos: usize,
    depth: usize,
    prev_ans: Option<f64>,
    angle: Angle,
}

impl Parser {
    fn peek(&self) -> Option<&Tok> {
        self.toks.get(self.pos)
    }

    fn peek_at(&self, n: usize) -> Option<&Tok> {
        self.toks.get(self.pos + n)
    }

    fn expr(&mut self) -> CResult {
        let mut left = self.term()?;
        loop {
            match self.peek() {
                Some(Tok::Op('+')) => {
                    self.pos += 1;
                    let r = self.term()?;
                    left = add(left, r);
                }
                Some(Tok::Op('-')) => {
                    self.pos += 1;
                    let r = self.term()?;
                    left = sub(left, r)?;
                }
                _ => break,
            }
        }
        Ok(left)
    }

    fn term(&mut self) -> CResult {
        let mut left = self.factor()?;
        loop {
            match self.peek() {
                Some(Tok::Op('*')) => {
                    self.pos += 1;
                    let r = self.factor()?;
                    left = left * r;
                }
                Some(Tok::Op('/')) => {
                    self.pos += 1;
                    let r = self.factor()?;
                    if r == 0.0 {
                        return Err(CalcErr::Math("Divide by zero error!".to_string()));
                    }
                    left = left / r;
                }
                Some(Tok::Op('%')) => {
                    self.pos += 1;
                    let r = self.factor()?;
                    left = left % r;
                }
                _ => break,
            }
        }
        Ok(left)
    }

    fn factor(&mut self) -> CResult {
        let mut sign = 0usize;
        loop {
            match self.peek() {
                Some(Tok::Op('+')) => {
                    self.pos += 1;
                }
                Some(Tok::Op('-')) => {
                    self.pos += 1;
                    sign += 1;
                }
                _ => break,
            }
        }
        let base = self.primary()?;
        let mut v = if sign % 2 == 1 { -base } else { base };
        if let Some(Tok::Op('^')) = self.peek() {
            self.pos += 1;
            let exp = self.factor()?;
            v = v.powf(exp);
        }
        Ok(v)
    }

    fn primary(&mut self) -> CResult {
        let t = match self.peek() {
            None => return Err(CalcErr::Parse("Too many operators, too few operands".into())),
            Some(t) => t.clone(),
        };
        match t {
            Tok::Num(v) => {
                self.pos += 1;
                Ok(v)
            }
            Tok::Const(name) => {
                self.pos += 1;
                Ok(constant(name))
            }
            Tok::Prev => {
                self.pos += 1;
                match self.prev_ans {
                    Some(p) => Ok(p),
                    None => Err(CalcErr::Syntax("No previous answer!".into())),
                }
            }
            Tok::LParen => {
                self.pos += 1;
                self.depth += 1;
                let v = self.expr()?;
                match self.peek() {
                    Some(Tok::RParen) => {
                        self.pos += 1;
                        self.depth -= 1;
                        Ok(v)
                    }
                    _ => Err(CalcErr::Syntax("Mismatched parentheses!".into())),
                }
            }
            Tok::RParen => {
                if self.depth == 0 {
                    Err(CalcErr::Syntax("Mismatched parentheses!".into()))
                } else {
                    Err(CalcErr::Parse("Too many operators, too few operands".into()))
                }
            }
            Tok::Comma => {
                if self.depth == 0 {
                    Err(CalcErr::Syntax("Mismatched parentheses!".into()))
                } else {
                    Err(CalcErr::Parse("Too many operators, too few operands".into()))
                }
            }
            Tok::Func(name) => {
                self.pos += 1;
                if self.peek() == Some(&Tok::LParen) {
                    self.call(name)
                } else if self.pos >= self.toks.len() {
                    Err(CalcErr::Parse("Too many operators, too few operands".into()))
                } else {
                    Err(CalcErr::Syntax(format!(
                        "Function '{}' expected parentheses",
                        name
                    )))
                }
            }
            Tok::Op(_) => Err(CalcErr::Parse("Too many operators, too few operands".into())),
            Tok::Unknown(_) => {
                Err(CalcErr::Parse("Too many operators, too few operands".into()))
            }
            Tok::Invalid(s) => Err(CalcErr::Syntax(format!("Unexpected character '{}'", s))),
            Tok::DotOp => {
                self.pos += 1;
                // behaves like an operator needing operands
                Err(CalcErr::Parse("Too many operators, too few operands".into()))
            }
        }
    }

    fn call(&mut self, name: &'static str) -> CResult {
        self.pos += 1; // consume '('
        self.depth += 1;
        let arity = known_arity(name);
        let mut args: Vec<f64> = Vec::new();
        let mut first = true;
        loop {
            // detect empty argument
            let empty = match self.peek() {
                Some(Tok::RParen) | Some(Tok::Comma) => true,
                _ => false,
            };
            let mut val: Option<f64> = None;
            if !empty {
                // an argument starting with a unary sign after the first is dropped
                let unary_start = matches!(self.peek(), Some(Tok::Op('+')) | Some(Tok::Op('-')))
                    && !first;
                match self.expr() {
                    Ok(v) => {
                        if !unary_start {
                            val = Some(v);
                        }
                    }
                    Err(e) => return Err(e),
                }
            }
            if let Some(v) = val {
                args.push(v);
            }
            first = false;
            match self.peek() {
                Some(Tok::Comma) => {
                    self.pos += 1;
                }
                Some(Tok::RParen) => {
                    self.pos += 1;
                    self.depth -= 1;
                    break;
                }
                None | Some(_) => {
                    // auto-balanced parentheses end of input
                    self.depth -= 1;
                    break;
                }
            }
        }
        if args.len() < arity {
            return Err(CalcErr::Parse(format!(
                "To few arguments for function, need {}",
                arity
            )));
        }
        if args.len() > arity {
            return Err(CalcErr::Parse("Too many operators, too few operands".into()));
        }
        apply_fn(name, &args, self.angle)
    }
}

fn constant(name: &str) -> f64 {
    match name {
        "pi" => std::f64::consts::PI,
        "e" => std::f64::consts::E,
        _ => 0.0,
    }
}

fn to_radians(x: f64, angle: Angle) -> f64 {
    match angle {
        Angle::Radian => x,
        Angle::Degree => x * std::f64::consts::PI / 180.0,
        Angle::Gradian => x * std::f64::consts::PI / 200.0,
    }
}

fn check_finite(v: f64) -> CResult {
    if v.is_finite() {
        Ok(v)
    } else {
        Err(CalcErr::Domain("Out of bounds!".into()))
    }
}

fn apply_fn(name: &str, args: &[f64], angle: Angle) -> CResult {
    let a = args[0];
    let r = match name {
        "sin" => to_radians(a, angle).sin(),
        "cos" => to_radians(a, angle).cos(),
        "tan" => to_radians(a, angle).tan(),
        "csc" => 1.0 / to_radians(a, angle).sin(),
        "sec" => 1.0 / to_radians(a, angle).cos(),
        "cot" => 1.0 / to_radians(a, angle).tan(),
        "sinh" => a.sinh(),
        "cosh" => a.cosh(),
        "tanh" => a.tanh(),
        "asin" => check_finite(a.asin())?,
        "acos" => check_finite(a.acos())?,
        "atan" => a.atan(),
        "acsc" => check_finite((1.0 / a).asin())?,
        "asec" => check_finite((1.0 / a).acos())?,
        "acot" => {
            let inv = 1.0 / a;
            check_finite(inv.atan())?
        }
        "ln" => check_finite(a.ln())?,
        "log2" => check_finite(a.log2())?,
        "log10" => check_finite(a.log10())?,
        "sqrt" => check_finite(a.sqrt())?,
        "ceil" => a.ceil(),
        "floor" => a.floor(),
        "abs" => a.abs(),
        "exp" => check_finite(a.exp())?,
        "round" => a.round(),
        "deg" => a * 180.0 / std::f64::consts::PI,
        "rad" => a * std::f64::consts::PI / 180.0,
        "log" => {
            let b = args[1];
            if a <= 0.0 {
                return Err(CalcErr::Domain("Out of bounds!".into()));
            }
            if b == 1.0 {
                return Err(CalcErr::Domain("Out of bounds!".into()));
            }
            check_finite(a.ln() / b.ln())?
        }
        "nroot" => {
            let n = args[1];
            if n == 0.0 {
                return Err(CalcErr::Domain("Out of bounds!".into()));
            }
            if a < 0.0 {
                return Err(CalcErr::Domain("Out of bounds!".into()));
            }
            a.powf(1.0 / n)
        }
        _ => return Err(CalcErr::Syntax(format!("Unknown function '{}'", name))),
    };
    Ok(r)
}

fn add(a: f64, b: f64) -> f64 {
    a + b
}

fn sub(a: f64, b: f64) -> CResult {
    Ok(a - b)
}

/// Evaluate an expression string.
pub fn calc(input: &str, angle: Angle, prev_ans: Option<f64>) -> CResult {
    let mut toks = tokenize(input);
    if toks.is_empty() {
        return Ok(0.0);
    }
    // auto-balance parentheses
    let mut opens = 0i32;
    for t in toks.iter() {
        match t {
            Tok::LParen => opens += 1,
            Tok::RParen => opens -= 1,
            _ => {}
        }
    }
    while opens > 0 {
        toks.push(Tok::RParen);
        opens -= 1;
    }
    if toks.iter().any(|t| matches!(t, Tok::Prev)) && prev_ans.is_none() {
        return Err(CalcErr::Syntax("No previous answer!".into()));
    }
    let mut p = Parser {
        toks,
        pos: 0,
        depth: 0,
        prev_ans,
        angle,
    };
    let v = p.expr()?;
    if p.pos < p.toks.len() {
        match &p.toks[p.pos] {
            Tok::RParen | Tok::Comma => {
                return Err(CalcErr::Syntax("Mismatched parentheses!".into()))
            }
            _ => return Err(CalcErr::Parse("Too many operators, too few operands".into())),
        }
    }
    if v.is_finite() {
        Ok(v)
    } else {
        Err(CalcErr::TooLarge)
    }
}
RUSTEOF
echo ok"}

