        match &p.toks[p.pos] {
            Tok::RParen | Tok::Comma => {
                return Err(CalcErr::Syntax("Mismatched parentheses!".into()))
            }
            _ => return Err(CalcErr::Parse("Too many operators, too few operands".into())),
