                                || ch == '^' || ch == '%'
                            {
                                i += 1;
                            } else if ch.is_ascii_digit() {
                                s.push(ch);
                                i += 1;
                                consumed = true;
                                break;
                            } else {
                                break;
                            }
                        }
                        flush_pending!();
                        if consumed {
                            toks.push(Tok::Invalid(s));
                        } else {
                            toks.push(Tok::Unknown(s));
                        }
