                i += 1;
                flush_pending!();
                toks.push(Tok::Op(c));
            }
            '(' => {
                i += 1;
                flush_pending!();
                toks.push(Tok::LParen);
            }
            ')' => {
                i += 1;
                flush_pending!();
                toks.push(Tok::RParen);
