                    if r == 0.0 {
                        return Err(CalcErr::Math("Divide by zero error!".to_string()));
                    }
                    left = left / r;
                }
                Some(Tok::Op('%')) => {
                    self.pos += 1;
                    let r = self.factor()?;
                    left = left % r;
                }
                _ => break,
            }
        }
        Ok(left)
    }

    fn factor(&mut self) -> CResult {
        let mut sign = 0usize;
        loop {
            match self.peek() {
                Some(Tok::Op('+')) => {
                    self.pos += 1;
                }
                Some(Tok::Op('-')) => {
                    self.pos += 1;
                    sign += 1;
                }
                _ => break,
