                // an argument starting with a unary sign after the first is dropped
                let unary_start = matches!(self.peek(), Some(Tok::Op('+')) | Some(Tok::Op('-')))
                    && !first;
                match self.expr() {
                    Ok(v) => {
                        if !unary_start {
                            val = Some(v);
