// Number formatting: decimal with thousands separators, or arbitrary radix.

/// Insert thousands separators (commas) every 3 digits counted from the right.
fn group_decimal(digits: &str) -> String {
    let n = digits.len();
    let mut out = String::with_capacity(n + n / 3);
    for (i, c) in digits.chars().enumerate() {
        if i > 0 && (n - i) % 3 == 0 {
            out.push(',');
        }
        out.push(c);
    }
    out
}

/// Insert commas every 3 characters, counting from the right.
fn group_every3(s: &str) -> String {
    let chars: Vec<char> = s.chars().collect();
    let n = chars.len();
    let mut out = String::with_capacity(n + n / 3);
    let mut i = 0usize;
    while i < n {
        out.push(chars[i]);
        let pos_from_right = n - 1 - i;
        if pos_from_right > 0 && pos_from_right % 3 == 0 {
            out.push(',');
        }
        i += 1;
    }
    out
}

fn digit_char(d: u32) -> char {
    if d < 10 {
        (b'0' + d as u8) as char
    } else {
        (b'A' + (d - 10) as u8) as char
    }
}

/// Convert a decimal integer digit string to the given radix (most significant first).
fn to_radix(dec: &str, base: u32) -> String {
    if base == 10 {
        return dec.to_string();
    }
    let mut digits: Vec<u8> = dec.chars().map(|c| c as u8 - b'0').collect();
    let mut out: Vec<char> = Vec::new();
    loop {
        // divide digits by base
        let mut q: Vec<u8> = Vec::with_capacity(digits.len());
        let mut rem: u32 = 0;
        for &d in digits.iter() {
            let cur = rem * 10 + d as u32;
            q.push((cur / base) as u8);
            rem = cur % base;
        }
        // strip leading zeros of quotient
        while let Some(&0) = q.first() {
            q.remove(0);
        }
        out.push(digit_char(rem));
        if q.is_empty() {
            break;
        }
        if base == 1 {
            // radix 1: division never terminates; emulate the hang of the original
            loop {
                std::thread::yield_now();
            }
        }
        digits = q;
    }
    if out.is_empty() {
        "0".to_string()
    } else {
        out.iter().rev().collect()
    }
}

/// Convert decimal fraction digits (numerator over 10^fix) into `count` digits
/// of the given radix.
fn frac_to_radix(frac_digits: &[u8], fix: usize, base: u32, count: usize) -> Vec<u32> {
    // little endian decimal digits of the numerator
    let mut num: Vec<u8> = frac_digits.iter().rev().copied().collect();
    while num.len() < fix {
        num.push(0);
    }
    let mut out = Vec::with_capacity(count);
    for _ in 0..count {
        // multiply by base
        let mut carry: u32 = 0;
        for d in num.iter_mut() {
            let v = *d as u32 * base + carry;
            *d = (v % 10) as u8;
            carry = v / 10;
        }
        while carry > 0 {
            num.push((carry % 10) as u8);
            carry /= 10;
        }
        // digit is the digit at position fix
        let digit = num.get(fix).copied().unwrap_or(0) as u32;
        out.push(digit);
        // truncate to fix digits (keep the remainder)
        if num.len() > fix {
            num.truncate(fix);
        }
        while num.len() < fix {
            num.push(0);
        }
    }
    out
}

