// Command line argument parsing, mimicking the help/error output of clap v4.

use crate::calc::Angle;

pub struct Args {
    pub fix: u32,
    pub base: u32,
    pub angle: Angle,
    pub input: Option<String>,
}

pub enum ArgErr {
    /// printed to stderr with exit code 2
    Msg(String),
    /// help/version printed to stdout, exit code 0
    Out(String),
}

const LONGS: &[&str] = &["fix", "base", "angle_unit", "help", "version"];

fn usage_line(prog: &str) -> String {
    format!("Usage: {} [OPTIONS] [INPUT]", prog)
}

fn usage_arg(prog: &str, arg: &str) -> String {
    match arg {
        "fix" => format!("Usage: {} --fix <FIX> [INPUT]", prog),
        "base" => format!("Usage: {} --base <RADIX> [INPUT]", prog),
        "angle_unit" => format!("Usage: {} --angle_unit <angle_unit> [INPUT]", prog),
        _ => usage_line(prog),
    }
}

fn canonical(arg: &str) -> &'static str {
    match arg {
        "fix" => "--fix <FIX>",
        "base" => "--base <RADIX>",
        "angle_unit" => "--angle_unit <angle_unit>",
        "help" => "--help",
        "version" => "--version",
        _ => "",
    }
}

fn possible_values(arg: &str) -> Option<&'static str> {
    if arg == "angle_unit" {
        Some("\n  [possible values: degree, radian, gradian]")
    } else {
        None
    }
}

/// Jaro-Winkler similarity, used to emulate clap's "did you mean" hints.
fn jaro_winkler(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let la = a.len();
    let lb = b.len();
    if la == 0 || lb == 0 {
        return if la == lb { 1.0 } else { 0.0 };
    }
    let window = (std::cmp::max(la, lb) / 2).saturating_sub(1);
    let mut a_match = vec![false; la];
    let mut b_match = vec![false; lb];
    let mut matches = 0usize;
    for i in 0..la {
        let start = i.saturating_sub(window);
        let end = std::cmp::min(i + window + 1, lb);
        for j in start..end {
            if !b_match[j] && a[i] == b[j] {
                a_match[i] = true;
                b_match[j] = true;
                matches += 1;
                break;
            }
        }
    }
    if matches == 0 {
        return 0.0;
    }
    let mut t = 0usize;
    let mut k = 0usize;
    for i in 0..la {
        if a_match[i] {
            while !b_match[k] {
                k += 1;
            }
            if a[i] != b[k] {
                t += 1;
            }
            k += 1;
        }
    }
    let m = matches as f64;
    let jaro = (m / la as f64 + m / lb as f64 + (m - t as f64 / 2.0) / m) / 3.0;
    let mut prefix = 0usize;
    for i in 0..std::cmp::min(la, lb).min(4) {
        if a[i] == b[i] {
            prefix += 1;
        } else {
            break;
        }
    }
    jaro + 0.1 * prefix as f64 * (1.0 - jaro)
}

fn similar_to(name: &str) -> Option<&'static str> {
    let mut best: Option<(&'static str, f64)> = None;
    for cand in LONGS {
        let score = jaro_winkler(name, cand);
        if score > 0.7 {
            match best {
                Some((_, s)) if s >= score => {}
                _ => best = Some((cand, score)),
            }
        }
    }
    best.map(|(c, _)| c)
}

fn err_unexpected(prog: &str, arg: &str) -> ArgErr {
    let body = arg.trim_start_matches('-');
    let tip = if let Some(sim) = similar_to(body) {
        (
            format!("  tip: a similar argument exists: '--{}'\n\n", sim),
            usage_arg(prog, sim),
        )
    } else {
        (
            format!("  tip: to pass '{}' as a value, use '-- {}'\n\n", arg, arg),
            usage_line(prog),
        )
    };
    ArgErr::Msg(format!(
        "error: unexpected argument '{}' found\n\n{}{}\n\nFor more information, try '--help'.\n",
        arg, tip.0, tip.1
    ))
}

fn err_unexpected_positional(prog: &str, arg: &str) -> ArgErr {
    ArgErr::Msg(format!(
        "error: unexpected argument '{}' found\n\n{}\n\nFor more information, try '--help'.\n",
        arg,
        usage_line(prog)
    ))
}

fn err_invalid_value(arg: &str, val: &str, reason: Option<&str>) -> ArgErr {
    let pv = possible_values(arg).unwrap_or("");
    let reason = match reason {
        Some(r) => format!(": {}", r),
        None => String::new(),
    };
    ArgErr::Msg(format!(
        "error: invalid value '{}' for '{}'\n{}{}\n\nFor more information, try '--help'.\n",
        val,
        canonical(arg),
        reason,
        pv
    ))
}

fn err_missing_value(arg: &str) -> ArgErr {
    let pv = possible_values(arg).unwrap_or("");
    ArgErr::Msg(format!(
        "error: a value is required for '{}' but none was supplied\n{}\n\nFor more information, try '--help'.\n",
        canonical(arg),
        pv
    ))
}

fn err_multiple(prog: &str, arg: &str) -> ArgErr {
    ArgErr::Msg(format!(
        "error: the argument '{}' cannot be used multiple times\n\n{}\n\nFor more information, try '--help'.\n",
        canonical(arg),
        usage_line(prog)
    ))
}

pub fn parse_help(prog: &str) -> String {
    format!(
        "Calculator REPL similar to bc(1)\n\nUsage: {prog} [OPTIONS] [INPUT]\n\nArguments:\n  [INPUT]  Optional expression string to run eva in command mode\n\nOptions:\n  -f, --fix <FIX>                Number of decimal places in output (1 - 64) [default: 10]\n  -b, --base <RADIX>             Radix of calculation output (1 - 36) [default: 10]\n  -a, --angle_unit <angle_unit>  Angle unit [default: degree] [possible values: degree, radian, gradian]\n  -h, --help                     Print help\n  -V, --version                  Print version\n",
        prog = prog
    )
}

struct State {
    fix: Option<u32>,
    base: Option<u32>,
    angle: Option<Angle>,
    input: Option<String>,
    fix_seen: bool,
    base_seen: bool,
    angle_seen: bool,
    trailing: bool,
}

fn set_value(st: &mut State, arg: &str, val: &str, prog: &str) -> Result<(), ArgErr> {
    match arg {
        "fix" | "base" => {
            let n: u32 = match val.parse() {
                Ok(v) => v,
                Err(_) => {
                    return Err(err_invalid_value(arg, val, Some("invalid digit found in string")))
                }
            };
            let (lo, hi) = if arg == "fix" { (1, 64) } else { (1, 36) };
            if n < lo || n > hi {
                return Err(err_invalid_value(
                    arg,
                    val,
                    Some(&format!("{} is not in {}..={}", n, lo, hi)),
                ));
            }
            if arg == "fix" {
                st.fix = Some(n);
            } else {
                st.base = Some(n);
            }
            Ok(())
        }
        "angle_unit" => {
            let a = match val {
                "degree" => Angle::Degree,
                "radian" => Angle::Radian,
                "gradian" => Angle::Gradian,
                _ => return Err(err_invalid_value(arg, val, None)),
            };
            st.angle = Some(a);
            Ok(())
        }
        _ => unreachable!(),
    }
}

pub fn parse(prog: &str, argv: &[String]) -> Result<Args, ArgErr> {
    let mut st = State {
        fix: None,
        base: None,
        angle: None,
        input: None,
        fix_seen: false,
        base_seen: false,
        angle_seen: false,
        trailing: false,
    };
    let mut i = 0usize;
    while i < argv.len() {
        let a = argv[i].clone();
        i += 1;
        if !st.trailing {
            if a == "--" {
                st.trailing = true;
                continue;
            }
            if a.starts_with("--") && a.len() > 2 {
                let body = &a[2..];
                let (name, val) = match body.find('=') {
                    Some(p) => (&body[..p], Some(body[p + 1..].to_string())),
                    None => (body, None),
                };
                match name {
                    "fix" | "base" | "angle_unit" => {
                        let seen = match name {
                            "fix" => &mut st.fix_seen,
                            "base" => &mut st.base_seen,
                            _ => &mut st.angle_seen,
                        };
                        if *seen {
                            return Err(err_multiple(prog, name));
                        }
                        let v = match val {
                            Some(v) => v,
                            None => match next_value(argv, &mut i)? {
                                Some(v) => v,
                                None => return Err(err_missing_value(name)),
                            },
                        };
                        *seen = true;
                        set_value(&mut st, name, &v, prog)?;
                    }
                    "help" => return Err(ArgErr::Out(parse_help(prog))),
                    "version" => return Err(ArgErr::Out("eva 0.3.1\n".to_string())),
                    _ => {
                        let shown = format!("--{}", name);
                        return Err(err_unexpected(prog, &shown));
                    }
                }
                continue;
            }
            if a.starts_with('-') && a.len() > 1 {
                let chars: Vec<char> = a[1..].chars().collect();
                let mut j = 0usize;
                while j < chars.len() {
                    let c = chars[j];
                    match c {
                        'h' => return Err(ArgErr::Out(parse_help(prog))),
                        'V' => return Err(ArgErr::Out("eva 0.3.1\n".to_string())),
                        'f' | 'b' | 'a' => {
                            let arg = match c {
                                'f' => "fix",
                                'b' => "base",
                                _ => "angle_unit",
                            };
                            let seen = match c {
                                'f' => &mut st.fix_seen,
                                'b' => &mut st.base_seen,
                                _ => &mut st.angle_seen,
                            };
                            if *seen {
                                return Err(err_multiple(prog, arg));
                            }
                            let rest: String = chars[j + 1..].iter().collect();
                            let v = if !rest.is_empty() {
                                if let Some(r) = rest.strip_prefix('=') {
                                    r.to_string()
                                } else {
                                    rest
                                }
                            } else {
                                match next_value(argv, &mut i)? {
                                    Some(v) => v,
                                    None => return Err(err_missing_value(arg)),
                                }
                            };
                            *seen = true;
                            set_value(&mut st, arg, &v, prog)?;
                            j = chars.len();
                        }
                        _ => {
                            let shown = format!("-{}", c);
                            return Err(err_unexpected(prog, &shown));
                        }
                    }
                }
                continue;
            }
        }
        if st.input.is_some() {
            return Err(err_unexpected_positional(prog, &a));
        }
        st.input = Some(a);
    }
    Ok(Args {
        fix: st.fix.unwrap_or(10),
        base: st.base.unwrap_or(10),
        angle: st.angle.unwrap_or(Angle::Degree),
        input: st.input,
    })
}

/// Fetch the value for an option from the next argument.
fn next_value(argv: &[String], i: &mut usize) -> Result<Option<String>, ArgErr> {
    if *i >= argv.len() {
        return Ok(None);
    }
    let a = &argv[*i];
    if a == "--" {
        return Ok(None);
    }
    if a.starts_with("--") && a.len() > 2 {
        // known long flag?
        let body = &a[2..];
        let name = match body.find('=') {
            Some(p) => &body[..p],
            None => body,
        };
        if LONGS.contains(&name) {
            return Ok(None);
        }
        *i += 1;
        return Err(err_unexpected("-e", a.as_str()));
