// Minimal terminal handling using ioctl via libc symbols.
#![allow(non_camel_case_types)]

#[repr(C)]
#[derive(Clone, Copy)]
pub struct Termios {
    pub c_iflag: u32,
    pub c_oflag: u32,
    pub c_cflag: u32,
    pub c_lflag: u32,
    pub c_line: u8,
    pub c_cc: [u8; 32],
    pub c_ispeed: u32,
    pub c_ospeed: u32,
}

#[repr(C)]
#[derive(Clone, Copy, Default)]
pub struct Winsize {
    pub ws_row: u16,
    pub ws_col: u16,
    pub ws_xpixel: u16,
    pub ws_ypixel: u16,
}

extern "C" {
    fn ioctl(fd: i32, request: u64, ...) -> i32;
    fn isatty(fd: i32) -> i32;
}

pub const TCGETS: u64 = 0x5401;
pub const TCSETS: u64 = 0x5402;
pub const TIOCGWINSZ: u64 = 0x5413;

// c_lflag bits
pub const ISIG: u32 = 0x00000001;
pub const ICANON: u32 = 0x00000002;
pub const ECHO: u32 = 0x00000008;
pub const ECHOE: u32 = 0x00000010;
pub const ECHOK: u32 = 0x00000020;
pub const ECHONL: u32 = 0x00000040;
pub const IEXTEN: u32 = 0x00008000;
// c_iflag bits
pub const IGNBRK: u32 = 0x00000001;
pub const BRKINT: u32 = 0x00000002;
pub const IGNPAR: u32 = 0x00000004;
pub const PARMRK: u32 = 0x00000008;
pub const ISTRIP: u32 = 0x00000020;
pub const INLCR: u32 = 0x00000040;
pub const IGNCR: u32 = 0x00000080;
pub const ICRNL: u32 = 0x00000100;
pub const IXON: u32 = 0x00000400;
pub const IXANY: u32 = 0x00000800;
pub const IXOFF: u32 = 0x00001000;

pub fn is_tty(fd: i32) -> bool {
    unsafe { isatty(fd) == 1 }
}

pub fn get_termios(fd: i32) -> Option<Termios> {
    let mut t = Termios {
        c_iflag: 0,
        c_oflag: 0,
        c_cflag: 0,
        c_lflag: 0,
        c_line: 0,
        c_cc: [0; 32],
        c_ispeed: 0,
        c_ospeed: 0,
    };
    let r = unsafe { ioctl(fd, TCGETS, &mut t as *mut Termios) };
    if r == 0 {
        Some(t)
    } else {
        None
    }
}

pub fn set_termios(fd: i32, t: &Termios) -> bool {
    let r = unsafe { ioctl(fd, TCSETS, t as *const Termios) };
    r == 0
}

