// Syntax highlighting used by the interactive line editor.

use crate::calc::{calc, Angle};

pub const RED: &str = "\x1b[31m";
pub const MAGENTA: &str = "\x1b[35m";
pub const BLUE: &str = "\x1b[34m";
pub const YELLOW: &str = "\x1b[33m";
pub const GRAY: &str = "\x1b[90m";
pub const RESET: &str = "\x1b[0m";

/// Returns the highlighted rendering of the input line.
pub fn highlight(input: &str, angle: Angle) -> String {
    if calc(input, angle, None).is_err() {
        return format!("{}{}{}", RED, input, RESET);
    }
    let src: Vec<char> = input.chars().collect();
    let mut out = String::new();
    let mut i = 0usize;
    while i < src.len() {
        let c = src[i];
        if c.is_ascii_alphanumeric() {
            let start = i;
            // leading letters
            while i < src.len() && src[i].is_ascii_alphabetic() {
                i += 1;
            }
            // digits
            while i < src.len() && src[i].is_ascii_digit() {
                i += 1;
            }
            // (letter followed by digits)*
            loop {
                if i < src.len() && src[i].is_ascii_alphabetic() {
                    if i + 1 < src.len() && src[i + 1].is_ascii_digit() {
                        i += 1;
                        while i < src.len() && src[i].is_ascii_digit() {
                            i += 1;
                        }
                        continue;
                    }
                    break;
                }
                break;
            }
            let word: String = src[start..i].iter().collect();
            if crate::calc::is_function_name(&word) {
                out.push_str(BLUE);
                out.push_str(&word);
                out.push_str(RESET);
            } else if word == "pi" || word == "e" {
                out.push_str(YELLOW);
                out.push_str(&word);
                out.push_str(RESET);
            } else {
                out.push_str(&word);
            }
            continue;
        }
        match c {
            '+' | '-' | '*' | '/' | '^' | '%' | '.' | ',' => {
                out.push_str(MAGENTA);
                out.push(c);
                out.push_str(RESET);
                i += 1;
            }
            _ => {
                out.push(c);
                i += 1;
            }
        }
    }
    out
}

/// Returns the suggestion (if any) that should be shown after `line`.
pub fn suggestion(line: &str, history: &[String]) -> Option<String> {
    if line.is_empty() {
        return None;
    }
    for h in history {
        if h.len() > line.len() && h.starts_with(line) {
            return Some(h[line.len()..].to_string());
        }
    }
    None
}
RUSTEOF
echo ok"}

