fn parse_key(pending: &mut Vec<u8>) -> Key {
    let c = pending[0];
    pending.remove(0);
    match c {
        b'\r' | b'\n' => Key::Enter,
        0x7f | 0x08 => Key::Backspace,
        0x1b => {
            if pending.is_empty() {
                return Key::Esc;
            }
            if pending[0] == b'[' {
                pending.remove(0);
                // read until final byte
                let mut params = String::new();
                while !pending.is_empty() {
                    let b = pending[0];
                    if b.is_ascii_digit() || b == b';' {
                        params.push(b as char);
                        pending.remove(0);
                    } else {
                        break;
                    }
                }
                if pending.is_empty() {
                    return Key::Other;
                }
                let fin = pending.remove(0);
                match fin {
                    b'A' => Key::Up,
                    b'B' => Key::Down,
                    b'C' => Key::Right,
                    b'D' => Key::Left,
                    b'H' => Key::Home,
                    b'F' => Key::End,
                    b'~' => match params.as_str() {
                        "1" | "7" => Key::Home,
                        "3" => Key::Delete,
                        "4" | "8" => Key::End,
                        _ => Key::Other,
                    },
                    _ => Key::Other,
                }
            } else if pending[0] == b'O' && pending.len() > 1 {
                let fin = pending[1];
                pending.remove(0);
                pending.remove(0);
                match fin {
                    b'A' => Key::Up,
                    b'B' => Key::Down,
                    b'C' => Key::Right,
                    b'D' => Key::Left,
                    _ => Key::Other,
                }
            } else if pending[0] == b'2' {
                // bracketed paste
                pending.remove(0);
                if pending.len() > 1 && pending[0] == b'0' {
                    pending.remove(0);
                    if pending.len() > 1 && pending[0] == b'0' {
                        pending.remove(0);
                        if pending.len() > 1 && pending[0] == b'~' {
                            pending.remove(0);
                            // paste mode on
                            return Key::Other;
                        }
                    }
                }
                Key::Other
            } else {
                let c2 = pending.remove(0);
                match c2 {
                    b'b' => Key::Char('W'), // backward word via Ctrl(W)? placeholder
                    b'f' => Key::Other,
                    b'd' => Key::Other,
                    0x7f | 0x08 => Key::Backspace,
                    _ => Key::Other,
                }
            }
        }
        c if c < 0x20 => Key::Ctrl(c),
        _ => {
            // decode utf8
            if c < 0x80 {
                Key::Char(c as char)
            } else {
                let need = if c >= 0xf0 {
                    4
                } else if c >= 0xe0 {
                    3
                } else {
                    2
                };
                let mut bytes = vec![c];
                while bytes.len() < need && !pending.is_empty() {
                    bytes.push(pending.remove(0));
                }
                match std::str::from_utf8(&bytes) {
                    Ok(s) => Key::Char(s.chars().next().unwrap()),
                    Err(_) => Key::Other,
                }
            }
        }
    }
}

