// Interactive line editor and REPL loop.

use crate::calc::{Angle, CalcErr, CResult};
use crate::fmt::format_value;
use crate::highlight::{highlight, suggestion, BLUE, GRAY, RESET};
use crate::term::{is_tty, winsize, RawMode};
use std::io::{Read, Write};

const PROMPT: &str = "> ";

pub struct Config {
    pub fix: usize,
    pub base: usize,
    pub angle: Angle,
    pub prev_ans: Option<f64>,
    pub history: Vec<String>,
}

#[derive(Clone, Copy, PartialEq)]
enum Key {
    Char(char),
    Enter,
    Backspace,
    Delete,
    Left,
    Right,
    Up,
    Down,
    Home,
    End,
    Tab,
    Ctrl(u8),
    Esc,
    Other,
}

fn display_width(s: &str) -> usize {
    s.chars()
        .filter(|c| !c.is_control() || *c == ' ')
        .count()
}

struct Editor {
    buf: Vec<char>,
    pos: usize,
    cols: usize,
    cur_row: usize,
    lines: usize,
    history_idx: Option<usize>,
    saved: Option<Vec<char>>,
    kill: String,
    searching: bool,
    search: String,
    search_failed: bool,
    search_match: Option<usize>,
}

impl Editor {
    fn new(cols: usize) -> Editor {
        Editor {
            buf: Vec::new(),
            pos: 0,
            cols,
            cur_row: 0,
            lines: 1,
            history_idx: None,
            saved: None,
            kill: String::new(),
            searching: false,
            search: String::new(),
            search_failed: false,
            search_match: None,
        }
    }

    fn is_word(c: char) -> bool {
        c.is_ascii_alphanumeric()
    }

    fn backward_word(&self) -> usize {
        let mut i = self.pos;
        while i > 0 && !Editor::is_word(self.buf[i - 1]) {
            i -= 1;
        }
        while i > 0 && Editor::is_word(self.buf[i - 1]) {
            i -= 1;
        }
        i
    }

    fn forward_word(&self) -> usize {
        let mut i = self.pos;
        while i < self.buf.len() && !Editor::is_word(self.buf[i]) {
            i += 1;
        }
        while i < self.buf.len() && Editor::is_word(self.buf[i]) {
            i += 1;
        }
        i
    }

    fn line_text(&self, cfg: &Config) -> String {
        let text: String = self.buf.iter().collect();
        if self.searching {
            let p = if self.search_failed {
                "(failed reverse-i-search)`".to_string()
            } else {
                "(reverse-i-search)`".to_string()
            };
            return format!("{}{}': {}", p, self.search, highlight(&text, cfg.angle));
        }
        let mut s = highlight(&text, cfg.angle);
        if self.pos == self.buf.len() {
            if let Some(sg) = suggestion(&text, &cfg.history) {
                s.push_str(GRAY);
                s.push_str(&sg);
                s.push_str(RESET);
            }
        }
        s
    }

    fn redraw(&mut self, out: &mut dyn Write, cfg: &Config) {
        let text = self.line_text(cfg);
        let _ = write!(out, "\x1b[?2026h");
        let _ = write!(out, "\r\x1b[K");
        while self.cur_row > 0 {
            let _ = write!(out, "\x1b[A\r\x1b[K");
            self.cur_row -= 1;
        }
        let _ = write!(out, "{}{}", PROMPT, text);
        // cursor positioning
        let total = PROMPT.len() + display_width(&self.buf.iter().collect::<String>());
        let end_row = if total == 0 { 0 } else { (total - 1) / self.cols };
        let abs = PROMPT.len() + self.pos;
        let trow = abs / self.cols;
        let tcol = abs % self.cols;
        if trow > end_row {
            for _ in 0..(trow - end_row) {
                let _ = write!(out, "\r\n");
            }
        } else if trow < end_row {
            let _ = write!(out, "\x1b[{}A", end_row - trow);
        }
        let _ = write!(out, "\r");
        if tcol > 0 {
            let _ = write!(out, "\x1b[{}C", tcol);
        }
        self.cur_row = trow;
        let _ = write!(out, "\x1b[?2026l");
        let _ = out.flush();
    }

    fn insert(&mut self, s: &str) {
        for c in s.chars() {
            self.buf.insert(self.pos, c);
            self.pos += 1;
        }
    }

    fn delete_backward(&mut self) {
        if self.pos > 0 {
            self.pos -= 1;
            self.buf.remove(self.pos);
        }
    }

    fn delete_forward(&mut self) {
        if self.pos < self.buf.len() {
            self.buf.remove(self.pos);
        }
    }
}

pub fn read_line(
    fd: i32,
    out: &mut dyn Write,
    cfg: &mut Config,
) -> Option<String> {
    let cols = winsize(fd).map(|(c, _)| if c == 0 { 80 } else { c as usize }).unwrap_or(80);
    let mut ed = Editor::new(cols);
    ed.redraw(out, cfg);
    let mut raw = [0u8; 1024];
    let mut reader = std::fs::File::from(unsafe { std::os::unix::io::FromRawFd::from_raw_fd(fd) });
    let mut pending: Vec<u8> = Vec::new();
    loop {
        // read one byte at a time
        let n = reader.read(&mut raw).unwrap_or(0);
        if n == 0 {
            return None;
        }
        pending.extend_from_slice(&raw[..n]);
        while !pending.is_empty() {
            let key = parse_key(&mut pending);
            match key {
                Key::Enter => {
                    ed.redraw(out, cfg);
                    let line: String = ed.buf.iter().collect();
                    return Some(line);
                }
                Key::Char(c) => {
                    ed.insert(&c.to_string());
                    ed.redraw(out, cfg);
                }
                Key::Backspace | Key::Ctrl(8) => {
                    ed.delete_backward();
                    ed.redraw(out, cfg);
                }
                Key::Ctrl(4) => {
                    if ed.buf.is_empty() {
                        return None;
                    }
                    ed.delete_forward();
                    ed.redraw(out, cfg);
                }
                Key::Delete => {
                    ed.delete_forward();
                    ed.redraw(out, cfg);
                }
                Key::Left | Key::Ctrl(2) => {
                    if ed.pos > 0 {
                        ed.pos -= 1;
                    }
                    ed.redraw(out, cfg);
                }
                Key::Right => {
                    if ed.pos < ed.buf.len() {
                        ed.pos += 1;
                    } else {
                        // accept suggestion
                        let text: String = ed.buf.iter().collect();
                        if let Some(sg) = suggestion(&text, &cfg.history) {
                            ed.insert(&sg);
                        }
                    }
                    ed.redraw(out, cfg);
                }
                Key::Ctrl(6) => {
                    if ed.pos < ed.buf.len() {
                        ed.pos += 1;
                        ed.redraw(out, cfg);
                    }
                }
                Key::Home | Key::Ctrl(1) => {
                    ed.pos = 0;
                    ed.redraw(out, cfg);
                }
                Key::End | Key::Ctrl(5) => {
                    ed.pos = ed.buf.len();
                    ed.redraw(out, cfg);
                }
                Key::Ctrl(21) => {
                    let text: String = ed.buf.iter().collect();
                    ed.kill = text;
                    ed.buf.clear();
                    ed.pos = 0;
                    ed.redraw(out, cfg);
                }
                Key::Ctrl(11) => {
                    let s: String = ed.buf[ed.pos..].iter().collect();
                    ed.kill = s;
                    ed.buf.truncate(ed.pos);
                    ed.redraw(out, cfg);
                }
                Key::Ctrl(23) | Key::Esc | Key::Char('W') => {
                    let p = ed.backward_word();
                    let s: String = ed.buf[p..ed.pos].iter().collect();
                    if let Key::Ctrl(23) = key {
                        ed.kill = s;
                    }
                    ed.buf.drain(p..ed.pos);
                    ed.pos = p;
                    ed.redraw(out, cfg);
                }
                Key::Ctrl(25) => {
                    let k = ed.kill.clone();
                    ed.insert(&k);
                    ed.redraw(out, cfg);
                }
                Key::Ctrl(12) => {
                    let _ = write!(out, "\x1b[H\x1b[J");
                    ed.redraw(out, cfg);
                }
                Key::Up => {
                    match ed.history_idx {
                        None => {
                            let saved = ed.buf.clone();
                            if let Some(i) = cfg.history.len().checked_sub(1) {
                                ed.saved = Some(saved);
                                ed.history_idx = Some(i);
                                ed.buf = cfg.history[i].chars().collect();
                                ed.pos = ed.buf.len();
                                ed.redraw(out, cfg);
                            }
                        }
                        Some(i) => {
                            if i > 0 {
                                ed.history_idx = Some(i - 1);
                                ed.buf = cfg.history[i - 1].chars().collect();
                                ed.pos = ed.buf.len();
                                ed.redraw(out, cfg);
                            }
                        }
                    }
                }
                Key::Down => {
                    match ed.history_idx {
                        None => {}
                        Some(i) => {
                            if i + 1 < cfg.history.len() {
                                ed.history_idx = Some(i + 1);
                                ed.buf = cfg.history[i + 1].chars().collect();
                                ed.pos = ed.buf.len();
                                ed.redraw(out, cfg);
                            } else {
                                ed.history_idx = None;
                                ed.buf = ed.saved.take().unwrap_or_default();
                                ed.pos = ed.buf.len();
                                ed.redraw(out, cfg);
                            }
                        }
                    }
                }
                Key::Ctrl(18) => {
                    if ed.searching {
                        // next search
                        if let Some(m) = ed.search_match {
                            if m > 0 {
                                ed.search_match = Some(m - 1);
                            } else {
                                ed.search_failed = true;
                                ed.search_match = None;
                            }
                        } else {
                            ed.search_failed = true;
                        }
                        ed.redraw(out, cfg);
                    } else {
                        ed.searching = true;
                        ed.search.clear();
                        ed.search_failed = false;
                        ed.search_match = None;
                        ed.redraw(out, cfg);
                    }
                }
                Key::Esc | Key::Ctrl(7) => {
                    if ed.searching {
                        ed.searching = false;
                        ed.search.clear();
                        ed.search_failed = false;
                        ed.redraw(out, cfg);
                    }
                }
                Key::Tab => {
                    // filename completion
                    let _ = out.write_all(&[7]);
                    let _ = out.flush();
                }
                Key::Ctrl(3) | Key::Ctrl(28) => {
                    let _ = write!(out, "\x1b[?2004l\r\nCTRL-C\r\n");
                    let _ = out.flush();
                    return None;
                }
                _ => {}
            }
        }
    }
}

