    let _ = std::fs::write(&p, "0");
}

pub fn read_prev_ans() -> Option<f64> {
    std::fs::read_to_string(prev_ans_path())
        .ok()
        .and_then(|s| s.trim().parse::<f64>().ok())
}

/// Run the interactive REPL.
pub fn run(cfg: &mut Config) {
    let fd = 0;
    let mut stdout = std::io::stdout();
    if !is_tty(fd) {
        // non-interactive: read lines from stdin
        let mut input = String::new();
        let _ = std::io::stdin().read_to_string(&mut input);
        for line in input.lines() {
            if line.trim().is_empty() {
                println!("0.{:0fill$}", 0, fill = cfg.fix);
                cfg.prev_ans = Some(0.0);
                continue;
            }
            match crate::calc::calc(line, cfg.angle, cfg.prev_ans) {
                Ok(v) => {
                    println!("{}", format_value(v, cfg.fix, cfg.base));
                    cfg.prev_ans = Some(v);
                    save_prev_ans(v);
                }
                Err(e) => {
                    println!("{}", e.message());
                    save_prev_ans_zero();
                }
            }
        }
        save_prev_ans(cfg.prev_ans.unwrap_or(0.0));
        return;
    }
    let _raw = RawMode::enter(fd);
    let mut out = std::io::stdout();
    if cfg.history.is_empty() {
        let _ = writeln!(out, "No previous history.");
        let _ = out.flush();
    }
    let _ = write!(out, "\x1b[?2004h");
    let _ = out.flush();
    loop {
        match read_line(fd, &mut out, cfg) {
            None => break,
            Some(line) => {
                let trimmed = line.trim().to_string();
                if trimmed.is_empty() {
                    cfg.prev_ans = Some(0.0);
                    save_prev_ans(0.0);
                    println!("0.{:0fill$}", 0, fill = cfg.fix);
                } else {
                    match crate::calc::calc(&trimmed, cfg.angle, cfg.prev_ans) {
                        Ok(v) => {
                            println!("{}", format_value(v, cfg.fix, cfg.base));
                            cfg.prev_ans = Some(v);
                            save_prev_ans(v);
                            add_history(cfg, &trimmed);
                        }
                        Err(e) => {
                            println!("{}", e.message());
                            save_prev_ans_zero();
                            add_history(cfg, &trimmed);
                        }
                    }
                }
                let _ = write!(out, "\x1b[?2004h");
                let _ = out.flush();
            }
        }
    }
    save_history(&cfg.history);
}

fn add_history(cfg: &mut Config, line: &str) {
    if cfg.history.last().map(|l| l.as_str()) == Some(line) {
        return;
    }
    cfg.history.push(line.to_string());
}
